CustomField.formula:
IF( No_Campaign_Members__c  -  No_Event_Registrations_ex_Guest__c  >= 0, 
     No_Campaign_Members__c  -  No_Event_Registrations_ex_Guest__c, 
     IF( No_Event_Registrations_ex_Guest__c  -  No_Campaign_Members__c  >= 0, 
         No_Event_Registrations_ex_Guest__c  -  No_Campaign_Members__c, 0 
     ) 
   )
